 // Legacy exercise IDs: retained so old workout history and saved plans remain readable.
 row:{name:'Wiosłowanie sztangą',group:'Plecy',sets:3,min:8,max:12,step:2.5,unit:'kg (sztanga)',photo:'Bent_Over_Barbell_Row',tip:'Utrzymuj neutralne plecy i prowadź łokcie w tył.'},
